/* A product's sales, rating and views are counted by Storelib, not typed by its seller (round AW, database security). products.sales_count, reviews_count, reviews_average and views are shown on the product page (the stars and the review count, the sales badge), on the creator page, in search, and rank Explore (components/explore/explore-page-client.tsx sorts by sales, review count and rating). Storelib keeps them: increment_product_sales and increment_product_views from the server, and the review trigger (update_product_review_stats) from published reviews. The owner update policy on products ("Creators can update their own products") checks only whose product it is, so with the public key a seller could write any of the four on their own product, a 5.0 from a thousand reviews and two thousand sales nobody made, and have Explore rank it first. The same four were already kept from the browser on creators (part 63, storelib_keep_server_columns). Now a write with the browser key (anon or authenticated) keeps their old values on an update and starts a new product at 0; the server and the three functions above count as before (they run as the service role or as their owner, which this does not touch), and no page writes them with the browser key: the product editor, the course builder and Duplicate never send them. Only these four columns; every other column of a product is saved exactly as before. It does NOT change any row. Skipped with a notice where products or one of the four columns is not here. LOCKS: CREATE TRIGGER takes a short lock on products, held until the paste ends. Safe to run again. */
CREATE OR REPLACE FUNCTION public.products_keep_counters() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF; IF TG_OP = 'INSERT' THEN NEW.sales_count := 0; NEW.reviews_count := 0; NEW.reviews_average := 0; NEW.views := 0; ELSE NEW.sales_count := OLD.sales_count; NEW.reviews_count := OLD.reviews_count; NEW.reviews_average := OLD.reviews_average; NEW.views := OLD.views; END IF; RETURN NEW; END $f$;
REVOKE ALL ON FUNCTION public.products_keep_counters() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 454: public.products does not exist here, skipped'; RETURN; END IF; IF (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products' AND column_name IN ('sales_count', 'reviews_count', 'reviews_average', 'views')) < 4 THEN RAISE NOTICE 'part 454: public.products lacks sales_count, reviews_count, reviews_average or views here, skipped'; RETURN; END IF; DROP TRIGGER IF EXISTS products_keep_counters ON public.products; CREATE TRIGGER products_keep_counters BEFORE INSERT OR UPDATE OF sales_count, reviews_count, reviews_average, views ON public.products FOR EACH ROW EXECUTE FUNCTION public.products_keep_counters(); END $do$;
notify pgrst, 'reload schema';
